using System;
using UnityEngine;

namespace Shura
{
    /// <summary>
    /// The hand-painted UI kit: sumi-e ink on washi paper, vermilion and gold. Textures are
    /// generated by Tools/ui_art/gen_ui.py (brush strokes simulated bristle by bristle) and
    /// live in Resources/UI; fonts are Kaushan Script (brush headings) and Spectral (text).
    /// Every primitive falls back to a flat drawing if its art is missing.
    /// </summary>
    public sealed class UiKit
    {
        // Ink on paper.
        public static readonly Color Ink = ColorUtil.Hex("#1E1A17");
        public static readonly Color InkSoft = ColorUtil.Hex("#5E5146");
        public static readonly Color Shu = ColorUtil.Hex("#B3261E");
        public static readonly Color ShuBright = ColorUtil.Hex("#D63A2C");
        public static readonly Color GoldInk = ColorUtil.Hex("#8C5E0C");
        public static readonly Color Ai = ColorUtil.Hex("#2D4F73");
        // Paper on ink.
        public static readonly Color PaperText = ColorUtil.Hex("#F1E8D6");
        public static readonly Color PaperDim = ColorUtil.Hex("#B9AC97");

        const int PaperBorder = 72;
        const int InkBorderX = 70;
        const int InkBorderY = 52;

        public Texture2D Paper, PaperDark, PanelPaper, PanelInk, StrokeWide, StrokeBar, StrokeFill, Divider,
                         EnsoTex, DabTex, LogoTex, SealTex, Backdrop, VignetteInk, PetalTex;
        public Texture2D[] Splats = new Texture2D[0];
        public Font Brush, Text, TextBold;

        GUIStyle paperPanel;
        GUIStyle inkPanel;
        Texture2D white;

        public bool HasArt => PanelPaper != null && StrokeWide != null;

        public void Load()
        {
            white = Texture2D.whiteTexture;
            Paper = Tex("paper_tile");
            PaperDark = Tex("paper_dark_tile");
            PanelPaper = Tex("panel_paper");
            PanelInk = Tex("panel_ink");
            StrokeWide = Tex("stroke_wide");
            StrokeBar = Tex("stroke_bar");
            StrokeFill = Tex("stroke_fill");
            Divider = Tex("divider");
            EnsoTex = Tex("enso");
            DabTex = Tex("dab");
            LogoTex = Tex("logo");
            SealTex = Tex("seal");
            Backdrop = Tex("backdrop");
            VignetteInk = Tex("vignette_ink");
            PetalTex = Tex("petal");
            Splats = new[] { Tex("splat_0"), Tex("splat_1"), Tex("splat_2") };
            Brush = Resources.Load<Font>("UI/Fonts/KaushanScript-Regular");
            Text = Resources.Load<Font>("UI/Fonts/Spectral-Medium");
            TextBold = Resources.Load<Font>("UI/Fonts/Spectral-SemiBold");

            if (PanelPaper != null)
            {
                paperPanel = new GUIStyle { border = new RectOffset(PaperBorder, PaperBorder, PaperBorder, PaperBorder) };
                paperPanel.normal.background = PanelPaper;
            }
            if (PanelInk != null)
            {
                inkPanel = new GUIStyle { border = new RectOffset(InkBorderX, InkBorderX, InkBorderY, InkBorderY) };
                inkPanel.normal.background = PanelInk;
            }
        }

        static Texture2D Tex(string name) => Resources.Load<Texture2D>("UI/" + name);

        static bool Repaint => Event.current == null || Event.current.type == EventType.Repaint;

        // ── Panels ──────────────────────────────────────────────────────────────────────

        /// <summary>Washi sheet with torn, scorched edges and a dry ink border.</summary>
        public void PaperPanel(Rect r, float alpha = 1f)
        {
            if (!Repaint) return;
            Color prev = GUI.color;
            if (paperPanel == null || Paper == null)
            {
                GUI.color = ColorUtil.Hex("#E9DFC8").WithAlpha(alpha);
                GUI.DrawTexture(r, white);
                GUI.color = prev;
                return;
            }
            GUI.color = new Color(1f, 1f, 1f, alpha);
            var inner = new Rect(r.x + 30f, r.y + 30f, r.width - 60f, r.height - 60f);
            GUI.DrawTextureWithTexCoords(inner, Paper, new Rect(r.x / 256f, r.y / 256f, inner.width / 256f, inner.height / 256f));
            paperPanel.Draw(r, GUIContent.none, false, false, false, false);
            GUI.color = prev;
        }

        /// <summary>A translucent ink wash with brushed, uneven edges (HUD backplates, dark boxes).</summary>
        public void InkPanel(Rect r, float alpha = 0.9f)
        {
            if (!Repaint) return;
            Color prev = GUI.color;
            GUI.color = new Color(1f, 1f, 1f, alpha);
            if (inkPanel != null) inkPanel.Draw(r, GUIContent.none, false, false, false, false);
            else
            {
                GUI.color = new Color(0.08f, 0.07f, 0.07f, 0.8f * alpha);
                GUI.DrawTexture(r, white);
            }
            GUI.color = prev;
        }

        // ── Brush marks ─────────────────────────────────────────────────────────────────

        /// <summary>A wide brush stroke, painted in from the left up to <paramref name="progress"/>.</summary>
        public void Stroke(Rect r, Color c, float progress = 1f)
        {
            Partial(StrokeWide, r, c, progress);
        }

        /// <summary>Ink-stroke gauge: a dry stroke behind, a wet stroke filling up to the ratio.</summary>
        public void Bar(Rect r, float ratio, Color fill, Color back, float ghost = 0f, Color ghostColor = default)
        {
            Draw(StrokeBar, r, back);
            if (ghost > ratio) Partial(StrokeFill, r, ghostColor, ghost);
            Partial(StrokeFill, r, fill, ratio);
        }

        public void Underline(Rect r, Color c) => Draw(Divider, r, c);

        public void Enso(Rect r, Color c, float degrees = 0f)
        {
            if (Mathf.Abs(degrees) < 0.01f) Draw(EnsoTex, r, c);
            else Rotated(r.center, degrees, () => Draw(EnsoTex, r, c));
        }

        public void Dab(Rect r, Color c) => Draw(DabTex, r, c);

        public void Splat(int index, Rect r, Color c)
        {
            if (Splats.Length == 0) return;
            Draw(Splats[Mathf.Abs(index) % Splats.Length], r, c);
        }

        public void Seal(Rect r, float alpha = 1f) => Draw(SealTex, r, new Color(1f, 1f, 1f, alpha));

        public void Logo(Rect r, Color c) => Draw(LogoTex, r, c);

        public void Petal(Rect r, float degrees, float alpha) =>
            Rotated(r.center, degrees, () => Draw(PetalTex, r, new Color(1f, 1f, 1f, alpha)));

        /// <summary>Covers the rect with the title painting, cropping (never stretching) it.</summary>
        public void Painting(Rect full, float drift)
        {
            if (Backdrop == null || !Repaint) return;
            float aspect = Backdrop.width / (float)Backdrop.height;
            float w = Mathf.Max(full.width, full.height * aspect) * 1.04f;
            float h = w / aspect;
            var r = new Rect(full.center.x - w * 0.5f + drift, full.center.y - h * 0.5f, w, h);
            Color prev = GUI.color;
            GUI.color = Color.white;
            GUI.DrawTexture(r, Backdrop);
            GUI.color = prev;
        }

        public void InkVignette(Rect full, Color c) => Draw(VignetteInk, full, c);

        // ── Helpers ─────────────────────────────────────────────────────────────────────

        void Draw(Texture2D tex, Rect r, Color c)
        {
            if (!Repaint) return;
            Color prev = GUI.color;
            GUI.color = c;
            GUI.DrawTexture(r, tex != null ? tex : white);
            GUI.color = prev;
        }

        /// <summary>Draws the left part of a texture, as if painted up to the given fraction.</summary>
        void Partial(Texture2D tex, Rect r, Color c, float fraction)
        {
            fraction = Mathf.Clamp01(fraction);
            if (fraction <= 0.001f || !Repaint) return;
            Color prev = GUI.color;
            GUI.color = c;
            var part = new Rect(r.x, r.y, r.width * fraction, r.height);
            if (tex != null) GUI.DrawTextureWithTexCoords(part, tex, new Rect(0f, 0f, fraction, 1f));
            else GUI.DrawTexture(part, white);
            GUI.color = prev;
        }

        /// <summary>
        /// Runs a draw rotated about a point in GUI space. Built on the current GUI.matrix
        /// directly (GUIUtility.RotateAroundPivot misplaces the pivot under the letterbox scale).
        /// </summary>
        public static void Rotated(Vector2 pivot, float degrees, Action draw)
        {
            Matrix4x4 saved = GUI.matrix;
            GUI.matrix = saved * Matrix4x4.TRS(pivot, Quaternion.Euler(0f, 0f, degrees), Vector3.one) * Matrix4x4.TRS(-pivot, Quaternion.identity, Vector3.one);
            draw();
            GUI.matrix = saved;
        }

        /// <summary>Darkens a bright UI colour so it reads on paper (rarity, element colours).</summary>
        public static Color OnPaper(Color c) => Color.Lerp(c, Ink, 0.42f).WithAlpha(c.a);

        /// <summary>"CONFIGURAÇÕES" → "Configurações": brush lettering reads best in sentence case.</summary>
        public static string Sentence(string text)
        {
            if (string.IsNullOrEmpty(text)) return text;
            string lower = text.ToLowerInvariant();
            return char.ToUpperInvariant(lower[0]) + lower.Substring(1);
        }
    }
}
